/**
 * Every researched outcome-web link either reaches an engine's own records
 * or is listed in src/core2/data/outcome-web/unwired.json with its exact
 * reason and an open stopgap that carries it. The list is regenerated by
 * scripts/outcome-web/write-unwired.ts; this fails when it and the effect
 * matrix disagree, so no link goes quiet.
 */
import { describe, expect, it } from "vitest";
import data from "./data/outcome-web/unwired.json" with { type: "json" };
import stopgaps from "./data/stopgaps.json" with { type: "json" };
import { unwiredRows } from "../../scripts/outcome-web/write-unwired";
import { linkCoverage, WEB_LINKS } from "./outcome-web-model";

describe("the outcome web's unwired links", () => {
  it("match the effect matrix, each with its reason", () => {
    expect(data.links).toEqual(unwiredRows());
    for (const row of data.links) expect(row.reason.length).toBeGreaterThan(20);
  });

  it("include every link the web does not run and no engine carries", () => {
    // An engine reading the outcome is not enough: a link the web does not
    // run moves nothing, so it stays on the list until it runs or is carried.
    const listed = new Set(data.links.map((row) => row.link));
    const unrun = WEB_LINKS.filter((link) => {
      const coverage = linkCoverage(link);
      return !coverage.wired && !("carriedBy" in coverage);
    });
    expect(unrun.length).toBeGreaterThan(0);
    // A link its research finds about zero has no effect to carry, so it is
    // graded not applicable and is not on the list (effect-matrix.ts).
    const aboutZero = (link: (typeof WEB_LINKS)[number]) =>
      (link as { status?: string }).status === "about-zero";
    for (const link of unrun)
      expect(listed.has(link.key), `${link.key} is not run`).toBe(
        !aboutZero(link),
      );
  });

  it("leave off every link its research finds about zero", () => {
    const listed = new Set(data.links.map((row) => row.link));
    const zero = WEB_LINKS.filter(
      (link) => (link as { status?: string }).status === "about-zero",
    );
    expect(zero.length).toBeGreaterThan(0);
    for (const link of zero) {
      expect(link.size, link.key).toBe(0);
      expect(listed.has(link.key), `${link.key} is about zero`).toBe(false);
    }
  });

  it("say the monthly ledger only for links the web runs", () => {
    // A link the web never runs moves nothing, not even the ledger; its
    // shared row must name its own reason instead.
    const rows = new Map(
      (stopgaps as { id: string; status?: string; whatItFakes?: string }[])
        .filter((row) => row.status === "open")
        .map((row) => [row.id, row.whatItFakes ?? ""]),
    );
    for (const row of data.links) {
      if (!row.stopgapId.startsWith("SG-WEB-unread-")) continue;
      const fakes = rows.get(row.stopgapId) ?? "";
      const runs = row.reason.startsWith("engine doesn't read");
      const clause =
        fakes.split("; ").find((part) => part.includes(row.link)) ?? "";
      expect(clause, `${row.link} in ${row.stopgapId}`).toContain(
        runs ? "monthly ledger" : "is not run by the outcome web",
      );
    }
  });

  it("each name an open stopgap row", () => {
    const open = new Set(
      (stopgaps as { id: string; status?: string }[])
        .filter((row) => row.status === "open")
        .map((row) => row.id),
    );
    for (const row of data.links)
      expect(open.has(row.stopgapId), `${row.link} ${row.stopgapId}`).toBe(
        true,
      );
  });
});
